import java.util.regex.*;

class Quadrant {
    public static String quadrant(String s) {
        Pattern pattern = Pattern.compile("(\\d+) + (\\d+)");
        Matcher matcher = pattern.matcher(s);
        if (matcher.find()) {
            String real = matcher.group(1);
            String imaginary = matcher.group(2);
            int x = Integer.parseInt(real);
            int y = Integer.parseInt(imaginary);
            if (x > 0 && y > 0) {
                return "Quadrant 1";
