mod = (int) (1e9 + 7)
factorial = [0] * N;
modinverse = [0] * N;
def power(a, m1):
    if(m1 == 0):
        return 1;
    elif(m1 == 1):
        return a;
    elif(m1 == 2):
        return(a * a) % mod;
    elif(m1 & 1):
        return(a * power(power(a, m1 // 2), 2)) % mod;
    else:
        return power(power(a, m1 // 2), 2) % mod;
def factorialfun():
    factorial[0] = 1;
    for i in range(1, N):
        factorial[i] = (factorial[i - 1] * i) % mod;
