public class PowerfulIntegers {
    public static void main(String[] args) {
        int x = 2;
        int y = 3;
        int bound = 10;
        powerfulIntegers(x, y, bound);
    }

    public static void powerfulIntegers(int x, int y, int bound) {
        Set<Integer> s = new HashSet<>();
        List<Integer> powersOfY = Arrays.asList(1);
        powersOfY.add(y);

        int i = y;
        while (i < bound && y != 1) {
            powersOfY.add(i);
            i *= y;
        }

        i = 0;
        while (true) {
            int xPowI = (int) Math.pow(x, i);
            for (int j : powersOfY) {
                int num = xPowI + j;
                if (num <= bound) {
                    s.add(num);
                } else {
                    break;
                }
            }
            if (xPowI >= bound || x == 1) {
                break;
            }
            i += 1;
        }

        for (int num : s) {
            System.out.print(num + " ▁ ");
        }
    }
}

