def count_odd_prime_factors(n):
    result = 1
    while n % 2 == 0:
        n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        div_count = 0
        while n % i == 0:
            n //= i
            div_count += 1
        result *= div_count + 1
    if n > 2:
        result *= 2
    return result

def politness(n):
    return count_odd_prime_factors(n) - 1

def main():
    n = 90
    print(f"Politness of {n} is {politness(n)}")

    n = 15
    print(f"Politness of {n} is {politness(n)}")

if __name__ == "__main__":
    main()

